//! Transport-neutral, bounded JSON packets. The shell supplies Hub, local tabs, or WebRTC.
use serde::{Serialize,Deserialize};
use glam::Vec3;
use crate::{Sim,SimEvent};
use super::*;
#[derive(Clone,Debug,Serialize,Deserialize)]pub struct Shot{pub origin:Vec3,pub direction:Vec3,pub weapon:usize,pub action:u32}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(tag="k")]pub enum Packet{
 #[serde(rename="p")]Pose{id:u8,p:[i32;3],y:i16,t:i16,h:i16,seat:i16,actions:Vec<Shot>},
 #[serde(rename="s")]Snapshot{tick:u64,n:Vec<[i32;7]>,v:Vec<[i32;7]>,p:Vec<[i32;7]>,score:i32,ledger:i32,lives:i32,time:i32,done:bool,won:bool},
 #[serde(rename="f")]Delta{version:u32,c:Vec<[i32;4]>,objects:Vec<usize>},
}
fn quant(v:Vec3)->[i32;3]{[(v.x*100.).round() as i32,(v.y*100.).round() as i32,(v.z*100.).round() as i32]}
fn unquant(v:[i32;3])->Vec3{Vec3::new(v[0] as f32,v[1] as f32,v[2] as f32)/100.}
impl Merc{
 pub fn net_trace(&mut self,a:Vec3,z:Vec3,hit:bool){self.traces.push(Trace{a,z,hit,life:0.16});if self.session&&!self.host{self.net_actions.push(Shot{origin:a,direction:(z-a).normalize_or_zero(),weapon:self.guns[self.active].def,action:0});}}
 pub fn pose_packet(&mut self)->Packet{Packet::Pose{id:self.local_id,p:quant(self.pos),y:self.yaw.to_degrees() as i16,t:self.pitch.to_degrees() as i16,h:self.health as i16,seat:self.riding.map(|i|i as i16).unwrap_or(-1),actions:std::mem::take(&mut self.net_actions)}}
 pub fn snapshot_packet(&self,tick:u64)->Packet{let mut n:Vec<_>=self.soldiers.iter().enumerate().filter(|(_,n)|distance(n.pos,self.pos)<180.||self.peers.iter().any(|p|p.present&&distance(p.pos,n.pos)<180.)).collect();n.sort_by(|a,b|distance(a.1.pos,self.pos).total_cmp(&distance(b.1.pos,self.pos)));let n=n.into_iter().take(8).map(|(i,n)|{let p=quant(n.pos);[i as i32,p[0],p[1],p[2],n.yaw.to_degrees() as i32,n.hp as i32,n.state as i32]}).collect();let v=self.vehicles.iter().enumerate().filter(|(_,v)|distance(v.pos,self.pos)<160.).take(3).map(|(i,v)|{let p=quant(v.pos);[i as i32,p[0],p[1],p[2],v.yaw.to_degrees() as i32,v.hp as i32,v.exploded as i32]}).collect();let mut p:Vec<_>=self.peers.iter().filter(|p|p.present).map(|p|{let q=quant(p.pos);[p.id as i32,q[0],q[1],q[2],p.yaw.to_degrees() as i32,p.hp as i32,p.seat]}).collect();if self.local_id!=255{let q=quant(self.pos);p.push([self.local_id as i32,q[0],q[1],q[2],self.yaw.to_degrees() as i32,self.health as i32,self.riding.map(|i|i as i32).unwrap_or(-1)]);}Packet::Snapshot{tick,n,v,p,score:self.team_score,ledger:self.ledger_carrier,lives:self.team_lives,time:(self.round_time*100.) as i32,done:self.finished,won:self.won}}
 pub fn delta_packet(&self,part:usize)->Packet{let c=self.fire.cells.iter().skip(part*350).take(350).map(|(&(x,z),c)|[x,z,c.state as i32,(c.time*4.) as i32]).collect();Packet::Delta{version:self.fire.version,c,objects:self.objects.iter().enumerate().filter(|(_,o)|o.exploded).map(|(i,_)|i).collect()}}
 pub fn receive(&mut self,sim:&mut Sim,from:u8,packet:Packet,events:&mut Vec<SimEvent>){if self.finished{return;}match packet{
 Packet::Pose{id,p,y,t,h,seat,actions} if self.host&&id==from=>{let pos=unquant(p);if !pos.is_finite(){return;}if let Some(peer)=self.peers.iter_mut().find(|peer|peer.id==id){peer.pos=pos;peer.yaw=(y as f32).to_radians();peer.pitch=(t as f32).to_radians();peer.hp=h as f32;peer.seat=seat as i32;}else{self.peers.push(Peer{id,pos,yaw:(y as f32).to_radians(),pitch:(t as f32).to_radians(),hp:h as f32,down:0.,seat:seat as i32,present:true,kills:0,rescues:0,jams:0});}
 for s in actions.into_iter().take(10){if s.origin.distance(pos)>5.||s.weapon>=self.data.weapons.len(){continue;}let saved=(self.pos,self.yaw,self.pitch,self.active,self.guns.clone(),self.health);self.pos=pos;self.yaw=s.direction.x.atan2(-s.direction.z);self.pitch=s.direction.y.clamp(-1.,1.).asin();let d=&self.data.weapons[s.weapon];self.active=d.slot;self.guns[self.active]=Gun::new(s.weapon,d,100.);if s.action==act::INTERACT{self.interact_goal(sim,events);}else if s.action==act::THROW{self.fire.ignite(&self.data,flat(pos+s.direction*18.),4.);}else{self.shoot(sim,events);}self.pos=saved.0;self.yaw=saved.1;self.pitch=saved.2;self.active=saved.3;self.guns=saved.4;self.health=saved.5;}
 },
 Packet::Snapshot{tick:_,n,v,p,score,ledger,lives,time,done,won} if !self.host=>{for a in n{if let Some(n)=self.soldiers.get_mut(a[0] as usize){n.pos=unquant([a[1],a[2],a[3]]);n.yaw=(a[4] as f32).to_radians();n.hp=a[5] as f32;n.state=a[6] as u8;}}for a in v{if let Some(v)=self.vehicles.get_mut(a[0] as usize){v.pos=unquant([a[1],a[2],a[3]]);v.yaw=(a[4] as f32).to_radians();v.hp=a[5] as f32;v.exploded=a[6]!=0;}}for a in p{let id=a[0] as u8;if id==self.local_id {continue;}let pos=unquant([a[1],a[2],a[3]]);if let Some(peer)=self.peers.iter_mut().find(|p|p.id==id){peer.pos=pos;peer.yaw=(a[4] as f32).to_radians();peer.hp=a[5] as f32;peer.seat=a[6];}else{self.peers.push(Peer{id,pos,yaw:(a[4] as f32).to_radians(),pitch:0.,hp:a[5] as f32,down:0.,seat:a[6],present:true,kills:0,rescues:0,jams:0});}}self.team_score=score;self.ledger_carrier=ledger;self.team_lives=lives;self.round_time=time as f32/100.;self.finished=done;self.won=won;},
 Packet::Delta{version,c,objects} if !self.host=>{for a in c{if a[2]==1||a[2]==2{self.fire.cells.insert((a[0],a[1]),fire::Cell{state:a[2] as u8,time:a[3] as f32/4.});}}self.fire.version=version;for i in objects{if let Some(o)=self.objects.get_mut(i){o.exploded=true;}}},_=>{}}}
 pub fn leave(&mut self,id:u8){if let Some(p)=self.peers.iter_mut().find(|p|p.id==id){p.present=false;}if self.ledger_carrier==id as i32{self.ledger_carrier=-1;}}
}
